  project(points, maxGames, maxGoals, w, h, padL, padT) {
    return points
      .map(function (p) {
        const x = padL + (p[0] / maxGames) * w;
        const y = padT + h - (p[1] / maxGoals) * h;
        return x.toFixed(1) + ',' + y.toFixed(1);
      })
      .join(' ');
  }

  buildRace(cfg) {
    const W = 280,
      H = 164,
      padL = 34,
      padT = 24;
    const plotBottom = padT + H;
    const proj = (pts) => this.project(pts, cfg.maxGames, cfg.maxGoals, W, H, padL, padT);
    const xAt = (g) => (padL + (g / cfg.maxGames) * W).toFixed(1);
    const yAt = (v) => (padT + H - (v / cfg.maxGoals) * H).toFixed(1);

    const hasHaaland = !!(cfg.haaland || cfg.haalandSolid);
    const hPts = hasHaaland ? cfg.haaland || cfg.haalandSolid : null;
    const fullHPts = hasHaaland ? (cfg.haalandDashed ? hPts.concat(cfg.haalandDashed) : hPts) : null;
    const hFinal = hasHaaland ? fullHPts[fullHPts.length - 1] : null;
    const hEndX = hasHaaland ? padL + (hFinal[0] / cfg.maxGames) * W : -999;
    const hEndY = hasHaaland ? padT + H - (hFinal[1] / cfg.maxGoals) * H : -999;

    const rivalEnds = cfg.rivals.map((r) => {
      const last = r.points[r.points.length - 1];
      return {
        key: r.key,
        x: padL + (last[0] / cfg.maxGames) * W,
        y: padT + H - (last[1] / cfg.maxGoals) * H,
      };
    });

    // de-collide label Y positions among Haaland (if present) + currently-toggled-on rivals,
    // so labels with close final values don't render on top of each other.
    const seeds = (hasHaaland ? [{ key: '__haaland', y: hEndY }] : []).concat(rivalEnds.filter((_, i) => cfg.rivals[i].on).map((e) => ({ key: e.key, y: e.y })));
    seeds.sort((a, b) => a.y - b.y);
    const minGap = 34;
    for (let i = 1; i < seeds.length; i++) {
      if (seeds[i].y - seeds[i - 1].y < minGap) seeds[i].y = seeds[i - 1].y + minGap;
    }
    const labelY = {};
    seeds.forEach((s) => {
      labelY[s.key] = s.y;
    });

    const rivals = cfg.rivals.map((r, i) => {
      const e = rivalEnds[i];
      return {
        key: r.key,
        name: r.short || r.name,
        color: r.color,
        points: proj(r.points),
        on: r.on,
        chipClass: 'rival-chip ' + (r.on ? 'on' : 'off'),
        dotX: e.x.toFixed(1),
        dotY: e.y.toFixed(1),
        labelX: (e.x + 7).toFixed(1),
        labelY: (r.on ? labelY[r.key] : e.y).toFixed(1),
        toggle: r.toggle,
      };
    });

    const xTickVals = [0, Math.round(cfg.maxGames / 2), cfg.maxGames];
    const yTickVals = [0, Math.round(cfg.maxGoals / 2), cfg.maxGoals];

    const areaPoints = hasHaaland ? proj(fullHPts) + ' ' + hEndX.toFixed(1) + ',' + plotBottom.toFixed(1) + ' ' + xAt(fullHPts[0][0]) + ',' + plotBottom.toFixed(1) : '';

    return {
      yTicks: yTickVals.map((v) => ({ v, y: yAt(v) })),
      xTicks: xTickVals.map((v) => ({ v, x: xAt(v) })),
      milestoneLineY: yAt(cfg.maxGoals),
      plotBottom: plotBottom.toFixed(1),
      haalandPoints: hasHaaland ? proj(hPts) : '',
      haalandDashedPoints: hasHaaland && cfg.haalandDashed ? proj(cfg.haalandDashed) : '',
      haalandAreaPoints: areaPoints,
      showProjection: hasHaaland && !!cfg.haalandDashed,
      haalandDotX: hEndX.toFixed(1),
      haalandDotY: hEndY.toFixed(1),
      haalandLabelX: (hEndX + 7).toFixed(1),
      haalandLabelY: (hasHaaland ? labelY['__haaland'] : hEndY).toFixed(1),
      rivals: rivals,
    };
  }

